var generateUPC = () => {
	const raw = `01${Date.now().toString().substr(-7)}${Math.floor(Math.random() * 1e3).toString().padStart(3, "0")}`;
	const digits = raw.split("").map(Number);
	let sum = 0;
	digits.forEach((d, i) => {
		sum += i % 2 === 0 ? d * 3 : d;
	});
	return `${raw}${(10 - sum % 10) % 10}`;
};
