			kind: "sale",
			productId: item.productId,
			productName: item.productName,
			quantity: 1,
			unitValue: item.price,
			value: item.price,
			reference: o.orderNumber,
			party: o.platform,
			serials: item.serial ? [item.serial] : [],
			note: "خروج عبر المنصة"
